  1→import { useCallback } from 'react';
  2→import { useFileUpload } from './useFileUpload';
  3→import { useFolder } from './useFolder';
  4→import { unpinFromIpfs } from '../lib/api/ipfs';
  5→import { useUploadStore } from '../stores/upload.store';
  6→import type { PendingReplacement } from '../stores/upload.store';
  7→import { useQuotaStore } from '../stores/quota.store';
  8→import { useFolderStore } from '../stores/folder.store';
  9→import type { UploadedFile } from '../services/upload.service';
 10→
 11→export const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB per FILE-01
 12→
 13→/**
 14→ * Check whether a drag event carries external files from the OS (Finder/Explorer)
 15→ * rather than an internal app drag (which sets application/json).
 16→ */
 17→export function isExternalFileDrag(dataTransfer: DataTransfer): boolean {
 18→  return dataTransfer.types.includes('Files') && !dataTransfer.types.includes('application/json');
 19→}
 20→
 21→/**
 22→ * Hook for handling external file drops (from Finder/Explorer) anywhere in the app.
 23→ *
 24→ * Provides a `handleFileDrop(files, folderId)` callback that validates,
 25→ * encrypts, uploads, and registers files in the target folder.
 26→ */
 27→export function useDropUpload() {
 28→  const { upload, canUpload, isUploading } = useFileUpload();
 29→  const { addFiles } = useFolder();
 30→
 31→  const handleFileDrop = useCallback(
 32→    async (files: File[], folderId: string): Promise<boolean> => {
 33→      // Filter out oversized files
 34→      const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
 35→      if (oversized.length > 0) {
 36→        useUploadStore
 37→          .getState()
 38→          .setError(`Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
 39→        return false;
 40→      }
 41→
 42→      if (files.length === 0) return false;
 43→
 44→      // Check quota
 45→      const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 46→      if (!canUpload(totalSize)) {
 47→        useUploadStore.getState().setError('Not enough storage space for these files');
 48→        return false;
 49→      }
 50→
 51→      // Check for duplicates within batch (independent of folder cache)
 52→      const batchNames = new Set<string>();
