 830→/**
 831→ * Move a file from one folder to another (v2).
 832→ *
 833→ * Uses add-before-remove pattern to prevent data loss on failure.
 834→ * FilePointer contains fileMetaIpnsName which stays the same across moves --
 835→ * no file IPNS record changes needed, only folder metadata changes.
 836→ *
 837→ * @param params.fileId - ID of file to move
 838→ * @param params.sourceFolderState - Current parent folder
 839→ * @param params.destFolderState - Destination folder
 840→ * @throws Error if file not found or name collision exists
 841→ */
 842→export async function moveFile(params: {
 843→  fileId: string;
 844→  sourceFolderState: FolderNode;
 845→  destFolderState: FolderNode;
 846→}): Promise<{ destSequenceNumber: bigint; sourceSequenceNumber: bigint }> {
 847→  // 1. Find file in source (v2: FilePointer)
 848→  const file = params.sourceFolderState.children.find(
 849→    (c) => c.type === 'file' && c.id === params.fileId
 850→  ) as FilePointer | undefined;
 851→
 852→  if (!file) throw new Error('File not found');
 853→
 854→  // 2. Check name collision in destination
 855→  const nameExists = params.destFolderState.children.some((c) => c.name === file.name);
 856→  if (nameExists) throw new Error('An item with this name already exists in destination');
 857→
 858→  // 3. ADD to destination FIRST
 859→  const destChildren: FolderChild[] = [
 860→    ...params.destFolderState.children,
 861→    {
 862→      ...file,
 863→      modifiedAt: Date.now(),
 864→    },
 865→  ];
 866→
 867→  const { newSequenceNumber: destSequenceNumber } = await updateFolderMetadata({
 868→    folderId: params.destFolderState.id,
 869→    children: destChildren,
 870→    folderKey: params.destFolderState.folderKey,
 871→    ipnsPrivateKey: params.destFolderState.ipnsPrivateKey,
 872→    ipnsName: params.destFolderState.ipnsName,
 873→    sequenceNumber: params.destFolderState.sequenceNumber,
 874→  });
 875→
 876→  // 4. REMOVE from source AFTER
 877→  const sourceChildren = params.sourceFolderState.children.filter(
 878→    (c) => !(c.type === 'file' && c.id === params.fileId)
 879→  );
 880→
 881→  const { newSequenceNumber: sourceSequenceNumber } = await updateFolderMetadata({
 882→    folderId: params.sourceFolderState.id,
 883→    children: sourceChildren,
 884→    folderKey: params.sourceFolderState.folderKey,
 885→    ipnsPrivateKey: params.sourceFolderState.ipnsPrivateKey,
 886→    ipnsName: params.sourceFolderState.ipnsName,
 887→    sequenceNumber:
 888→      params.sourceFolderState.id === params.destFolderState.id
 889→        ? destSequenceNumber
 890→        : params.sourceFolderState.sequenceNumber,
 891→  });
 892→
 893→  return { destSequenceNumber, sourceSequenceNumber };
 894→}
