 896→/**
 897→ * Rename a file within its parent folder (v2).
 898→ *
 899→ * Updates the FilePointer's name in the parent's metadata and publishes
 900→ * an updated IPNS record for the parent folder.
 901→ * File rename does NOT touch the file's own IPNS record -- only folder metadata.
 902→ *
 903→ * @param params.fileId - ID of file to rename
 904→ * @param params.newName - New name for the file
 905→ * @param params.parentFolderState - Parent folder containing this file
 906→ * @throws Error if file not found or name collision exists
 907→ */
 908→export async function renameFile(params: {
 909→  fileId: string;
 910→  newName: string;
 911→  parentFolderState: FolderNode;
 912→}): Promise<{ newSequenceNumber: bigint }> {
 913→  const children = [...params.parentFolderState.children];
 914→  const fileIndex = children.findIndex((c) => c.type === 'file' && c.id === params.fileId);
 915→
 916→  if (fileIndex === -1) throw new Error('File not found');
 917→
 918→  // Check name collision
 919→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.fileId);
 920→  if (nameExists) throw new Error('An item with this name already exists');
 921→
 922→  const file = children[fileIndex] as FilePointer;
 923→  children[fileIndex] = {
 924→    ...file,
 925→    name: params.newName,
 926→    modifiedAt: Date.now(),
 927→  };
 928→
 929→  const { newSequenceNumber } = await updateFolderMetadata({
 930→    folderId: params.parentFolderState.id,
 931→    children,
 932→    folderKey: params.parentFolderState.folderKey,
 933→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 934→    ipnsName: params.parentFolderState.ipnsName,
 935→    sequenceNumber: params.parentFolderState.sequenceNumber,
 936→  });
 937→
 938→  return { newSequenceNumber };
 939→}
