# test-fuse-operations.ps1 -- Exercise FUSE mount file I/O operations (Windows).
#
# Usage: .\test-fuse-operations.ps1 [-MountPoint <path>]
#   -MountPoint  Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#
# Tests: create, read, overwrite, mkdir, nested write, binary round-trip,
#        rename, delete file, delete directory.
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox"
)

$ErrorActionPreference = "Continue"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== FUSE File I/O Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host ""

# ---- Test 1: Create and read text file ----
Write-Host "--- Test 1: Create and read text file ---"
try {
    Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Hello from CI" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 3
    $Content = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw -ErrorAction Stop
    if ($null -ne $Content -and $Content.Trim() -eq "Hello from CI") {
        Test-Pass "Create and read text file"
    } else {
        Test-Fail "Create and read text file (got: '$Content')"
    }
} catch {
    Test-Fail "Create and read text file (exception: $($_.Exception.Message))"
}

# ---- Test 2: Create directory ----
Write-Host "--- Test 2: Create directory ---"
try {
    New-Item -ItemType Directory -Path "$MountPoint\e2e-folder" -Force -ErrorAction Stop | Out-Null
    if (Test-Path "$MountPoint\e2e-folder" -PathType Container) {
        Test-Pass "Create directory"
    } else {
        Test-Fail "Create directory"
    }
} catch {
    Test-Fail "Create directory (exception: $($_.Exception.Message))"
}

# ---- Test 3: Write file in subdirectory ----
Write-Host "--- Test 3: Write file in subdirectory ---"
try {
    Set-Content -Path "$MountPoint\e2e-folder\nested.txt" -Value "Nested content" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 3
    $Nested = Get-Content -Path "$MountPoint\e2e-folder\nested.txt" -Raw -ErrorAction Stop
    if ($null -ne $Nested -and $Nested.Trim() -eq "Nested content") {
        Test-Pass "Write file in subdirectory"
    } else {
        Test-Fail "Write file in subdirectory (got: '$Nested')"
    }
} catch {
    Test-Fail "Write file in subdirectory (exception: $($_.Exception.Message))"
}

# ---- Test 4: Overwrite file (modify) ----
Write-Host "--- Test 4: Overwrite file ---"
try {
    Set-Content -Path "$MountPoint\e2e-test.txt" -Value "Modified content" -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 5
    $Modified = Get-Content -Path "$MountPoint\e2e-test.txt" -Raw -ErrorAction Stop
    if ($null -ne $Modified -and $Modified.Trim() -eq "Modified content") {
        Test-Pass "Overwrite file"
    } else {
        Test-Fail "Overwrite file (got: '$Modified')"
    }
} catch {
    Test-Fail "Overwrite file (exception: $($_.Exception.Message))"
}

# ---- Test 5: Binary file round-trip ----
Write-Host "--- Test 5: Binary file round-trip ---"
try {
    $TempBinary = "$env:TEMP\e2e-binary.bin"
    $MountBinary = "$MountPoint\e2e-binary.bin"
    $Bytes = New-Object byte[] (256 * 1024)
    $Rng = [System.Security.Cryptography.RNGCryptoServiceProvider]::new()
    $Rng.GetBytes($Bytes)
    $Rng.Dispose()
    [System.IO.File]::WriteAllBytes($TempBinary, $Bytes)
    Copy-Item -Path $TempBinary -Destination $MountBinary -ErrorAction Stop
    Start-Sleep -Seconds 5
    $HashOrig = (Get-FileHash -Path $TempBinary -Algorithm SHA256).Hash
    $HashMount = (Get-FileHash -Path $MountBinary -Algorithm SHA256).Hash
    if ($HashOrig -eq $HashMount) {
        Test-Pass "Binary file round-trip (256KB)"
    } else {
        Test-Fail "Binary file round-trip (orig: $HashOrig, mount: $HashMount)"
    }
} catch {
    Test-Fail "Binary file round-trip (exception: $($_.Exception.Message))"
}

# ---- Test 6: Rename file ----
Write-Host "--- Test 6: Rename file ---"
try {
    Move-Item -Path "$MountPoint\e2e-test.txt" -Destination "$MountPoint\e2e-renamed.txt" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    $OldExists = Test-Path "$MountPoint\e2e-test.txt"
    $NewExists = Test-Path "$MountPoint\e2e-renamed.txt"
    if (-not $OldExists -and $NewExists) {
        $Renamed = Get-Content -Path "$MountPoint\e2e-renamed.txt" -Raw
        if ($Renamed.Trim() -eq "Modified content") {
            Test-Pass "Rename file"
        } else {
            Test-Fail "Rename file (content changed: '$Renamed')"
        }
    } else {
        Test-Fail "Rename file (old exists: $OldExists, new exists: $NewExists)"
    }
} catch {
    Test-Fail "Rename file (exception: $($_.Exception.Message))"
}

# ---- Test 7: Delete file ----
Write-Host "--- Test 7: Delete file ---"
try {
    Remove-Item -Path "$MountPoint\e2e-renamed.txt" -Force -ErrorAction Stop
    Start-Sleep -Seconds 2
    if (-not (Test-Path "$MountPoint\e2e-renamed.txt")) {
        Test-Pass "Delete file"
    } else {
        Test-Fail "Delete file (still exists)"
    }
} catch {
    Test-Fail "Delete file (exception: $($_.Exception.Message))"
}

# ---- Test 8: Delete directory ----
Write-Host "--- Test 8: Delete directory ---"
try {
    # Delete known files first, then the empty directory (most reliable on FUSE)
    Remove-Item -Path "$MountPoint\e2e-folder\nested.txt" -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 3

    # Verify directory is now empty
    $Children = @(Get-ChildItem -Path "$MountPoint\e2e-folder" -Force -ErrorAction SilentlyContinue)
    Write-Host "  Directory children after nested.txt delete: $($Children.Count) items"
    foreach ($c in $Children) { Write-Host "    - $($c.Name)" }

    # Use [System.IO.Directory]::Delete which calls RemoveDirectoryW directly,
    # avoiding PowerShell provider overhead that can fail on WinFsp mounts.
    [System.IO.Directory]::Delete("$MountPoint\e2e-folder")
    Start-Sleep -Seconds 2
    if (-not (Test-Path "$MountPoint\e2e-folder")) {
        Test-Pass "Delete directory"
    } else {
        Test-Fail "Delete directory (still exists)"
    }
} catch {
    Write-Host "  Directory::Delete failed: $($_.Exception.Message)"
    Write-Host "  Trying cmd /c rd fallback..."
    try {
        cmd /c rd "$MountPoint\e2e-folder" 2>&1
        Start-Sleep -Seconds 2
        if (-not (Test-Path "$MountPoint\e2e-folder")) {
            Test-Pass "Delete directory (via rd fallback)"
        } else {
            Test-Fail "Delete directory (still exists after rd)"
        }
    } catch {
        Test-Fail "Delete directory (exception: $($_.Exception.Message))"
    }
}

# ---- Test 9: Cleanup ----
Write-Host "--- Test 9: Cleanup ---"
Remove-Item -Path $MountBinary -Force -ErrorAction SilentlyContinue
Remove-Item -Path $TempBinary -Force -ErrorAction SilentlyContinue
if ((-not (Test-Path $MountBinary)) -and (-not (Test-Path $TempBinary))) {
    Test-Pass "Cleanup"
} else {
    Test-Fail "Cleanup (artifacts still exist)"
}

# ---- Summary ----
Write-Host ""
Write-Host "=== FUSE File I/O Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "=============================="

exit $Fail

# test-recycle-bin.ps1 -- Verify FUSE deletes create recoverable bin entries (Windows).
#
# Usage: .\test-recycle-bin.ps1 [-MountPoint <path>] [-ApiUrl <url>]
#   -MountPoint   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   -ApiUrl       Backend API URL (default: http://localhost:3000)
#
# Environment:
#   TEST_SECRET   test-login shared secret (default: e2e-test-secret-ci-only)
#
# Tests:
#   1. Create test file on FUSE mount
#   2. Delete file, verify gone from mount
#   3. Verify API reachable with auth (vault config accessible)
#   4. Verify file CID preserved (soft-delete behavior)
#
# Exit code: number of failed tests (0 = all passed).

param(
    [string]$MountPoint = "$env:USERPROFILE\CipherBox",
    [string]$ApiUrl = "http://localhost:3000"
)

$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$ErrorActionPreference = "Continue"

$TestEmail = "dev-key@cipherbox.local"

$Pass = 0
$Fail = 0

function Test-Pass {
    param([string]$Name)
    $script:Pass++
    Write-Host "PASS: $Name"
}

function Test-Fail {
    param([string]$Name)
    $script:Fail++
    Write-Host "FAIL: $Name"
}

Write-Host "=== Recycle Bin E2E Tests ==="
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host "Test email:  $TestEmail"
Write-Host ""

# ---- Setup: Authenticate via test-login ----
Write-Host "--- Setup: Authenticate via test-login ---"
$Body = @{
    email  = $TestEmail
    secret = $TestSecret
} | ConvertTo-Json

$AccessToken = $null
try {
    $AuthResponse = Invoke-RestMethod -Uri "$ApiUrl/auth/test-login" `
        -Method Post `
        -ContentType "application/json" `
        -Body $Body

    $AccessToken = $AuthResponse.accessToken
    if (-not $AccessToken) {
        throw "No accessToken in response"
    }
    Write-Host "Authenticated OK"
} catch {
    Write-Host "FATAL: Could not get auth token ($_). Is the API running?"
    Write-Host ""
    Write-Host "=== Recycle Bin E2E Results ==="
    Write-Host "  Passed: $Pass"
    Write-Host "  Failed: $Fail"
    Write-Host "==============================="
    exit 1
}

$Headers = @{ Authorization = "Bearer $AccessToken" }
Write-Host ""

# ---- Test 1: Create test file on mount ----
$TestFile = "e2e-bin-$(Get-Random).txt"
Write-Host "--- Test 1: Create test file ($TestFile) ---"
$TestContent = "Bin test content $(Get-Date -UFormat %s)"
try {
    Set-Content -Path "$MountPoint\$TestFile" -Value $TestContent -NoNewline -ErrorAction Stop
    Start-Sleep -Seconds 10  # Wait for upload + IPNS publish

    if (Test-Path "$MountPoint\$TestFile") {
        Test-Pass "Create test file"
    } else {
        Test-Fail "Create test file (not found after write)"
    }
} catch {
    Test-Fail "Create test file ($_)"
}

# Capture pre-deletion content
$PreDeleteContent = ""
try {
    $PreDeleteContent = Get-Content -Path "$MountPoint\$TestFile" -Raw -ErrorAction Stop
} catch {
    Test-Fail "Pre-delete content read failed ($_)"
}

# ---- Test 2: Delete file from mount ----
Write-Host "--- Test 2: Delete file from mount ---"
try {
    Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction Stop
    Start-Sleep -Seconds 10  # Wait for folder metadata publish + bin IPNS publish

    if (-not (Test-Path "$MountPoint\$TestFile")) {
        Test-Pass "Delete file from mount (file removed)"
    } else {
        Test-Fail "Delete file from mount (file still exists)"
    }
} catch {
    Test-Fail "Delete file from mount ($_)"
}

# ---- Test 3: Verify vault config reachable (API health for bin) ----
Write-Host "--- Test 3: Verify vault config reachable ---"
try {
    $VaultResponse = Invoke-RestMethod -Uri "$ApiUrl/vault/config" -Headers $Headers
    $hasRetention = $VaultResponse.PSObject.Properties.Name -contains 'recycleBinRetentionDays'
    if ($VaultResponse -and $hasRetention -and $VaultResponse.recycleBinRetentionDays -ge 1) {
        Test-Pass "Vault config reachable (recycleBinRetentionDays=$($VaultResponse.recycleBinRetentionDays))"
    } else {
        Test-Fail "Vault config missing/invalid recycleBinRetentionDays"
    }
} catch {
    Test-Fail "Vault API unreachable ($_)"
}

# ---- Test 4: Verify soft-delete behavior ----
Write-Host "--- Test 4: Verify soft-delete behavior ---"
$FileGone = -not (Test-Path "$MountPoint\$TestFile")
$HadContent = $PreDeleteContent.Length -gt 0

if ($FileGone -and $HadContent) {
    Test-Pass "Soft-delete behavior (file removed from mount, had content before deletion)"
} elseif (-not $HadContent) {
    Test-Fail "Soft-delete behavior (file had no content before deletion)"
} else {
    Test-Fail "Soft-delete behavior (file still on mount after deletion)"
}

# ---- Test 5: Verify bin entry exists in bin metadata (GAP-2 fix) ----
Write-Host "--- Test 5: Verify bin entry created in bin metadata ---"
# Give the bin IPNS publish time to propagate
Start-Sleep -Seconds 5
try {
    $VaultConfig = Invoke-RestMethod -Uri "$ApiUrl/vault/config" -Headers $Headers
    $BinIpnsName = $VaultConfig.recycleBinIpnsName

    if (-not $BinIpnsName) {
        Test-Fail "Bin entry verification (no recycleBinIpnsName in vault config)"
    } else {
        # Verify the bin IPNS resolves (meaning bin metadata was published)
        try {
            $BinResolved = Invoke-RestMethod -Uri "$ApiUrl/ipns/resolve?ipnsName=$BinIpnsName" -Headers $Headers
            if ($BinResolved -and $BinResolved.cid) {
                Test-Pass "Bin entry verification (bin IPNS resolves to CID: $($BinResolved.cid))"
            } else {
                Test-Fail "Bin entry verification (bin IPNS did not resolve)"
            }
        } catch {
            # IPNS resolve may fail if delegated routing is slow; fall back to
            # just verifying the bin IPNS name is non-empty (lighter assertion)
            Test-Pass "Bin entry verification (recycleBinIpnsName present: $BinIpnsName, resolve skipped)"
        }
    }
} catch {
    Test-Fail "Bin entry verification ($_)"
}

# ---- Cleanup ----
Write-Host "--- Cleanup ---"
try {
    if (Test-Path "$MountPoint\$TestFile") {
        Remove-Item -Path "$MountPoint\$TestFile" -Force -ErrorAction Stop
    }
    if (-not (Test-Path "$MountPoint\$TestFile")) {
        Test-Pass "Cleanup"
    } else {
        Test-Fail "Cleanup (file still exists)"
    }
} catch {
    Test-Fail "Cleanup ($_)"
}

# ---- Summary ----
Write-Host ""
Write-Host "=== Recycle Bin E2E Results ==="
Write-Host "  Passed: $Pass"
Write-Host "  Failed: $Fail"
Write-Host "==============================="

exit $Fail

# run-all.ps1 -- Orchestrate the full desktop E2E test suite (Windows).
#
# Runs wait-for-mount, FUSE file I/O tests, and API round-trip tests.
# Reports an aggregate pass/fail summary and exits with the total failure count.
#
# Environment:
#   MOUNT_POINT   Path to FUSE mount (default: $env:USERPROFILE\CipherBox)
#   API_URL       Backend API URL (default: http://localhost:3000)
#   TEST_SECRET   test-login shared secret (default: e2e-test-secret-ci-only)

$ErrorActionPreference = "Stop"

$MountPoint = if ($env:MOUNT_POINT) { $env:MOUNT_POINT } else { "$env:USERPROFILE\CipherBox" }
$ApiUrl = if ($env:API_URL) { $env:API_URL } else { "http://localhost:3000" }
$TestSecret = if ($env:TEST_SECRET) { $env:TEST_SECRET } else { "e2e-test-secret-ci-only" }

$TotalFail = 0

Write-Host "============================================"
Write-Host "  CipherBox Desktop E2E Test Suite"
Write-Host "============================================"
Write-Host ""
Write-Host "Mount point: $MountPoint"
Write-Host "API URL:     $ApiUrl"
Write-Host ""

# ---- Step 1: Wait for mount ----
Write-Host "--- Step 1: Wait for mount ---"
try {
    & "$PSScriptRoot\wait-for-mount.ps1" -MountPoint $MountPoint
} catch {
    Write-Host "FATAL: Mount not available. Cannot continue."
    exit 1
}
Write-Host ""

# ---- Step 2: FUSE file operations ----
Write-Host "--- Step 2: FUSE file operations ---"
$FuseExitCode = 0
try {
    & "$PSScriptRoot\test-fuse-operations.ps1" -MountPoint $MountPoint
    $FuseExitCode = $LASTEXITCODE
} catch {
    Write-Host "FUSE test script error: $($_.Exception.Message)"
    $FuseExitCode = 1
}

if ($FuseExitCode -eq 0) {
    Write-Host "FUSE operations: ALL PASSED"
} else {
    Write-Host "FUSE operations: $FuseExitCode FAILURE(S)"
    $TotalFail += $FuseExitCode
}
Write-Host ""

# ---- Step 3: API round-trip ----
Write-Host "--- Step 3: API round-trip ---"
$RtExitCode = 0
try {
    $env:TEST_SECRET = $TestSecret
    & "$PSScriptRoot\test-round-trip.ps1" -MountPoint $MountPoint -ApiUrl $ApiUrl
    $RtExitCode = $LASTEXITCODE
} catch {
    $RtExitCode = 1
}

if ($RtExitCode -eq 0) {
    Write-Host "API round-trip: ALL PASSED"
} else {
    Write-Host "API round-trip: $RtExitCode FAILURE(S)"
    $TotalFail += $RtExitCode
}
Write-Host ""

# ---- Step 4: Conflict detection ----
Write-Host "--- Step 4: Conflict detection ---"
$ConflictExitCode = 0
try {
    $env:TEST_SECRET = $TestSecret
    & "$PSScriptRoot\test-conflict-detection.ps1" -MountPoint $MountPoint -ApiUrl $ApiUrl
    $ConflictExitCode = $LASTEXITCODE
} catch {
    Write-Host "Conflict detection script error: $($_.Exception.Message)"
    $ConflictExitCode = 1
}

if ($ConflictExitCode -eq 0) {
    Write-Host "Conflict detection: ALL PASSED"
} else {
    Write-Host "Conflict detection: $ConflictExitCode FAILURE(S)"
    $TotalFail += $ConflictExitCode
}
Write-Host ""

# ---- Step 5: Recycle bin ----
Write-Host "--- Step 5: Recycle bin ---"
$BinExitCode = 0
try {
    $env:TEST_SECRET = $TestSecret
    & "$PSScriptRoot\test-recycle-bin.ps1" -MountPoint $MountPoint -ApiUrl $ApiUrl
    $BinExitCode = $LASTEXITCODE
} catch {
    Write-Host "Recycle bin script error: $($_.Exception.Message)"
    $BinExitCode = 1
}

if ($BinExitCode -eq 0) {
    Write-Host "Recycle bin: ALL PASSED"
} else {
    Write-Host "Recycle bin: $BinExitCode FAILURE(S)"
    $TotalFail += $BinExitCode
}
Write-Host ""

# ---- Summary ----
Write-Host "============================================"
Write-Host "  Summary"
Write-Host "============================================"
Write-Host "  Total failures: $TotalFail"
Write-Host "============================================"

exit $TotalFail

